/**
 * Yjs Binary Compatibility Test
 *
 * Validates that Yjs updates generated by Go y-crdt can be decoded by JavaScript Yjs.
 * This ensures wire-format compatibility between the Go worker and JavaScript frontend.
 *
 * The base64 update below comes from tests/unit/yjs_compat_test.go.
 * To update after y-crdt library upgrade:
 *   1. Run: go test -v ./tests/unit -run TestYjsCompatibility
 *   2. Copy the base64 output and update the constant below
 *   3. Run: make test
 * @module unit-tests/yjs-compat-test
 */

import { assert } from '../utilities/test-helpers.js';

/**
 * @typedef {object} TestContext
 * @property {string} fixtureDir - Fixture directory (not used by this test)
 */

/**
 * @typedef {object} TestResult
 * @property {number} passed - Number of passed tests
 * @property {number} failed - Number of failed tests
 * @property {string[]} errors - Error messages for failed tests
 */

// Base64 update from Go y-crdt test (tests/unit/yjs_compat_test.go)
// Updated: 2026-03-08 (Y.Map migration)
const GO_UPDATE_BASE64 = 'AQTjttyTBwAHAQVpdGVtcwEoAOO23JMHAAR0eXBlAXcEdXNlcigA47bckwcAB2NvbnRlbnQBdw1IZWxsbywgV29ybGQhKADjttyTBwAGaXRlbUlkAXcHbXNnXzEyMwA=';

/**
 * Decode base64 to Uint8Array using browser API
 * @param {string} base64 - Base64 encoded string
 * @returns {Uint8Array} Decoded bytes
 */
function base64ToUint8Array(base64) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Run Yjs compatibility tests.
 * @param {TestContext} _ctx - Test context (unused - this test doesn't need fixtures)
 * @returns {Promise<TestResult>} Test results
 */
export async function runTests(_ctx) {
  let passed = 0;
  let failed = 0;
  /** @type {string[]} */
  const errors = [];

  // Import Yjs from vendor
  const Y = await import('../../js/vendor/yjs.mjs');

  // Test: Decode Go-generated Yjs update
  try {
    // Create a new Yjs document
    const doc = new Y.Doc();
    const items = doc.getArray('items');

    // Verify initial state
    assert(items.length === 0, 'Initial items array should be empty');

    // Decode the Go-generated update
    const updateBytes = base64ToUint8Array(GO_UPDATE_BASE64);

    // Apply the update
    Y.applyUpdate(doc, updateBytes);

    // Verify the update was applied
    assert(items.length === 1, `Expected 1 item after apply, got ${items.length}`);

    // Get the decoded item - should be Y.Map after migration
    const firstItem = items.get(0);

    // Verify it's a Y.Map
    assert(firstItem instanceof Y.Map, `Item should be a Y.Map, got ${firstItem?.constructor?.name}`);

    // Verify the content matches what Go encoded via Y.Map .get()
    assert(firstItem.get('type') === 'user', `Expected type 'user', got '${firstItem.get('type')}'`);
    assert(firstItem.get('content') === 'Hello, World!', `Expected content 'Hello, World!', got '${firstItem.get('content')}'`);
    assert(firstItem.get('itemId') === 'msg_123', `Expected itemId 'msg_123', got '${firstItem.get('itemId')}'`);

    passed++;
  } catch (e) {
    failed++;
    errors.push(`Yjs decode: ${e instanceof Error ? e.message : String(e)}`);
  }

  return { passed, failed, errors };
}
